import React, { useState } from 'react';
import { Text, View, Button, TouchableOpacity } from 'react-native';

import { ParamListBase, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';

type YourNavigatorProps = NativeStackNavigationProp<ParamListBase, keyof ParamListBase>

import { styles } from './styles'

export default function Checkout() {
    const navigation = useNavigation<YourNavigatorProps>();

    return (
        <View style={styles.container}>
            <TouchableOpacity style={{ backgroundColor: '#555', width: 0, height: 0, top: 0, position: 'absolute' }} onPress={() => navigation.navigate('Home')} />



            <View style={{
                backgroundColor: '#fff',
                height: '90%',
                width: '90%',
                borderRadius: 10,
                alignItems: 'center'
            }}>
                <View>
                    <Text style={{
                        fontSize: 40,
                        color: '#000',
                        top: 15,
                        paddingVertical: 7
                    }}>Pagamento Pix</Text>
                </View>


                <View>
                    <Text style={{
                        fontSize: 20,
                        color: '#000',
                        top: 15,
                        paddingVertical: 7
                    }}>Pagar com Pix é facil é rápido!</Text>

                    <Text style={{
                        fontSize: 20,
                        color: '#000',
                        width: '95%',
                        padding: 10
                    }}> • Abra o seu aplicativo Pix do seu Banco ou empresa de Pagamento.</Text>

                    <Text style={{
                        fontSize: 20,
                        color: '#000',
                        width: '95%',
                        padding: 10
                    }}> • Clique em Pagar Pix no seu Aplicativo e aponte a câmera para o QR Code Pix.</Text>

                    <Text style={{
                        fontSize: 20,
                        color: '#000',
                        width: '95%',
                        padding: 10
                    }}> • Pronto, agora é só finalizar o pagamento e aguardar a Aprovação.</Text>

                    <Text style={{
                        fontSize: 20,
                        color: '#000',
                        width: '95%',
                        padding: 10
                    }}> • Se preferir, Copie e Cole o Código Pix no seu Aplicativo ou Site Pix.</Text>

                </View>


            </View>
        </View >
    )
}
